begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
\ir ../fixtures/agenda.psql
update private.bc_finance_settings set simple_mode=true where id;
update public.staff_profiles set profissao='Profissional CI',conselho='Conselho fictício',registro_conselho='CI' where user_id=pg_temp.f('worker');
insert into public.consent_template_versions(consent_class,version,title,body) values('nao_injetavel',9999,'Termo fictício CI','Banco descartável de teste.');
insert into public.client_files(id,cliente_id,title,category,origin,storage_path,mime_type,size_bytes,sha256,uploaded_by)
values('b3000000-0000-4000-8000-000000000099',pg_temp.f('client'),'TCLE fictício CI','tcle_externo','upload_manual','arquivos-clientes/ci/consentimento.pdf','application/pdf',3,repeat('0',64),pg_temp.f('worker'));
select set_config('request.jwt.claim.sub',pg_temp.f('admin')::text,true);
set local role authenticated;
insert into fixture values('free-proc',public.bc_procedure_save_draft(null,'{"nome":"Avaliação gratuita CI","classe_documental":"nao_injetavel","price_mode":"fixed","base_price":0,"protocol_mode":"simple","requires_general_anamnesis":false}'));
select lives_ok(format('select public.bc_procedure_publish(%L)',pg_temp.f('free-proc')),'publicar gratuito explícito');
insert into fixture values('unknown-proc',public.bc_procedure_save_draft(null,'{"nome":"Valor a definir CI","classe_documental":"nao_injetavel","price_mode":"fixed","base_price":null,"protocol_mode":"simple","requires_general_anamnesis":false}'));
select lives_ok(format('select public.bc_procedure_publish(%L)',pg_temp.f('unknown-proc')),'publicar com valor a definir');
select set_config('request.jwt.claim.sub',pg_temp.f('worker')::text,true);
insert into fixture values('free-agenda',public.bc_agendamento_create(pg_temp.f('client'),pg_temp.f('worker'),pg_temp.f('free-proc'),(select slot from test_clock)));
insert into fixture values('unknown-agenda',public.bc_agendamento_create(pg_temp.f('client'),pg_temp.f('worker'),pg_temp.f('unknown-proc'),(select slot+interval '1 hour' from test_clock)));
insert into fixture values('free-treatment',public.bc_treatment_create(pg_temp.f('client'),pg_temp.f('free-proc'),pg_temp.f('free-agenda')));
insert into fixture values('unknown-treatment',public.bc_treatment_create(pg_temp.f('client'),pg_temp.f('unknown-proc'),pg_temp.f('unknown-agenda')));
select public.bc_treatment_update_draft(pg_temp.f('free-treatment'),'{"objetivo":"Fixture clínica gratuita","regiao":"Face"}');
select public.bc_treatment_update_draft(pg_temp.f('unknown-treatment'),'{"objetivo":"Fixture clínica sem valor","regiao":"Face","final_price":null}');
select public.bc_treatment_confirm_health(pg_temp.f('free-treatment'),false,null);
select public.bc_treatment_confirm_health(pg_temp.f('unknown-treatment'),false,null);
select public.bc_treatment_confirm_alerts(pg_temp.f('free-treatment'));
select public.bc_treatment_confirm_alerts(pg_temp.f('unknown-treatment'));
select public.bc_treatment_external_consent_link(pg_temp.f('free-treatment'),'b3000000-0000-4000-8000-000000000099');
select public.bc_treatment_external_consent_link(pg_temp.f('unknown-treatment'),'b3000000-0000-4000-8000-000000000099');
select public.bc_treatment_mark_ready(pg_temp.f('free-treatment'));
select public.bc_treatment_mark_ready(pg_temp.f('unknown-treatment'));
select public.bc_treatment_start(pg_temp.f('free-treatment'));
select public.bc_treatment_start(pg_temp.f('unknown-treatment'));
select throws_ok(format('select public.bc_treatment_finalize(%L)',pg_temp.f('free-treatment')),'55000',null,'gratuidade não remove parecer obrigatório');
select public.bc_treatment_report_upsert(pg_temp.f('free-treatment'),'{"descricao_sessao":"Sessão fictícia CI","resposta_observada":"Fixture","orientacoes":"Fixture CI"}');
select public.bc_treatment_report_upsert(pg_temp.f('unknown-treatment'),'{"descricao_sessao":"Sessão fictícia CI","resposta_observada":"Fixture","orientacoes":"Fixture CI"}');
insert into fixture select 'free-doc',(public.bc_treatment_finalize(pg_temp.f('free-treatment'))->>'document_id')::uuid;
insert into fixture select 'unknown-doc',(public.bc_treatment_finalize(pg_temp.f('unknown-treatment'))->>'document_id')::uuid;
select throws_ok(format('select public.bc_treatment_complete_finalize(%L,%L)',pg_temp.f('free-treatment'),pg_temp.f('free-doc')),'22023',null,'gratuidade não remove assinatura obrigatória');
reset role;
-- Assinaturas fictícias de fixture; nenhum arquivo ou assinatura de pessoa real.
insert into public.clinical_signatures(document_id,signer_kind,signer_user_id,signer_name,storage_path,sha256,recorded_by)
select id,'profissional',pg_temp.f('worker'),'Profissional fictícia CI','assinaturas/ci/'||id||'.png',repeat('0',64),pg_temp.f('worker') from fixture where name in ('free-doc','unknown-doc');
set local role authenticated;
select lives_ok(format('select public.bc_treatment_complete_finalize(%L,%L)',pg_temp.f('free-treatment'),pg_temp.f('free-doc')),'gratuito completa por API autorizada');
select lives_ok(format('select public.bc_treatment_complete_finalize(%L,%L)',pg_temp.f('unknown-treatment'),pg_temp.f('unknown-doc')),'sem preço completa por API autorizada');
select is(public.bc_finance_appointment_summary(pg_temp.f('free-agenda'))->>'state','free','gratuito sem entrada fictícia');
select is(public.bc_finance_appointment_summary(pg_temp.f('unknown-agenda'))->>'state','missing_total','valor indefinido explícito');
select throws_ok(format('select public.bc_finance_charge_define(%L,200)',pg_temp.f('unknown-agenda')),'42501',null,'colaboradora não define cobrança administrativa');
select set_config('request.jwt.claim.sub',pg_temp.f('admin')::text,true);
select is(jsonb_array_length(public.bc_finance_overview(current_date,current_date)->'charge_issues'),1,'gratuito não aparece como cobrança pendente');
insert into fixture values('defined-charge',public.bc_finance_charge_define(pg_temp.f('unknown-agenda'),200));
select is(public.bc_finance_charge_define(pg_temp.f('unknown-agenda'),200),pg_temp.f('defined-charge'),'definição repetida não duplica cobrança');
select throws_ok(format('select public.bc_finance_charge_define(%L,300)',pg_temp.f('unknown-agenda')),'55000',null,'outro total não substitui cobrança');
select is((public.bc_finance_appointment_summary(pg_temp.f('unknown-agenda'))->>'remaining')::numeric,200::numeric,'cobrança libera recebimento');
reset role;
select is((select count(*)::integer from public.pagamentos where agendamento_id=pg_temp.f('free-agenda')),0,'gratuito não cria cobrança');
select is((select count(*)::integer from public.recebimentos),0,'conclusão e cobrança não criam receita');
select is((select v.snapshot->'treatment'->>'final_price' from public.clinical_treatments t join public.clinical_treatment_versions v on v.id=t.current_version_id where t.id=pg_temp.f('unknown-treatment')),null::text,'documento permanece congelado sem preço inventado');
select * from finish();rollback;
